import{_ as e,c as o,o as d,b2 as a}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"安全防护（Web 防火墙）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/security-module.md","filePath":"docs/backend/modules/security-module.md"}'),r={name:"docs/backend/modules/security-module.md"};function l(i,t,c,s,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="安全防护-web-防火墙" tabindex="-1">安全防护（Web 防火墙） <a class="header-anchor vp-link" href="#安全防护-web-防火墙" aria-label="Permalink to &quot;安全防护（Web 防火墙）&quot;">​</a></h1><p>横切能力位于 <strong><code>quickboot-common</code></strong> 的 <code>security.firewall</code> 包，通过 <code>qc.security.firewall.*</code> 配置开关，在请求进入 Controller 前执行。</p><h2 id="模块一览" tabindex="-1">模块一览 <a class="header-anchor vp-link" href="#模块一览" aria-label="Permalink to &quot;模块一览&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模块</th><th>配置前缀（示意）</th><th>作用</th></tr></thead><tbody><tr><td>安全响应头</td><td><code>security.firewall.headers</code></td><td>CSP、HSTS、X-Frame-Options 等</td></tr><tr><td>CORS</td><td><code>security.firewall.cors</code></td><td>跨域白名单</td></tr><tr><td>XSS</td><td><code>security.firewall.xss</code></td><td>请求体/参数 XSS 过滤（含 multipart）</td></tr><tr><td>SQL 注入</td><td><code>security.firewall.sql-injection</code></td><td>关键字检测；可配置忽略 JSON 字段</td></tr><tr><td>敏感词</td><td><code>security.firewall.sensitive-word</code></td><td>黑白名单（houbb/sensitive-word）</td></tr><tr><td>幂等</td><td><code>security.firewall.idempotent</code></td><td>幂等 Token，Caffeine/Redis 存储</td></tr><tr><td>Method/Host</td><td><code>security.firewall.methodandhost</code></td><td>允许的方法与 Host 白名单</td></tr><tr><td>密码编解码</td><td><code>security.firewall.password.codec</code></td><td>BCrypt + SM4（<code>QC_SM4_KEY_HEX</code>）</td></tr></tbody></table></div><h2 id="与业务的关系" tabindex="-1">与业务的关系 <a class="header-anchor vp-link" href="#与业务的关系" aria-label="Permalink to &quot;与业务的关系&quot;">​</a></h2><ul><li><strong>登录</strong>：<code>AuthController</code> + Sa-Token；可配置图形/行为验证码（<code>qc.login.captcha-enabled</code>、<code>captcha.*</code>）。</li><li><strong>匿名路径</strong>：<code>qc.security.web.anonymous-paths</code>（如静态资源、OAuth 部分端点）。</li><li><strong>Client 签名</strong>：<code>qc.security.client-sign</code>（见 <a href="./client-management.html" class="vp-link">客户端管理</a>）。</li></ul><h2 id="sql-注入与-oauth-配置" tabindex="-1">SQL 注入与 OAuth 配置 <a class="header-anchor vp-link" href="#sql-注入与-oauth-配置" aria-label="Permalink to &quot;SQL 注入与 OAuth 配置&quot;">​</a></h2><p><code>sys_oauth_client.api_path_patterns</code> 若含 <code>/**</code>，可能触发 SQL 防火墙误报；已在配置中对相应 JSON 字段做忽略（见 <a href="./oauth2.html" class="vp-link">OAuth2 集成</a>）。</p><h2 id="操作日志脱敏" tabindex="-1">操作日志脱敏 <a class="header-anchor vp-link" href="#操作日志脱敏" aria-label="Permalink to &quot;操作日志脱敏&quot;">​</a></h2><p><code>monitor.operlog</code> 采集请求参数/结果时经 <code>OperLogSensitiveMasker</code> 脱敏，避免密码、token 落库。</p><h2 id="开发建议" tabindex="-1">开发建议 <a class="header-anchor vp-link" href="#开发建议" aria-label="Permalink to &quot;开发建议&quot;">​</a></h2><ul><li>新增公开接口时同步更新 <strong>匿名路径</strong> 或 <strong>Client 签名校验</strong> 策略，避免 401/403。</li><li>富文本（公告）使用 OWASP HTML Sanitizer（web 模块），与 XSS 过滤器互补。</li><li>生产关闭 Druid StatView、收紧 Actuator 暴露面（见 <code>application-prod.yml</code>）。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../components/通用组件/异常处理模块使用文档.html" class="vp-link">异常处理模块</a></li><li><a href="./oauth2.html" class="vp-link">OAuth2 集成</a></li></ul>',14)])])}const m=e(r,[["render",l]]);export{p as __pageData,m as default};
